class Solution {
    public List<Integer> fallingSquares(int[][] positions) {
        List<Integer> result = new java.util.ArrayList<>();
        int[] heights = new int[positions.length];
        int maxH = 0;
        for (int i = 0; i < positions.length; i++) {
            int left = positions[i][0], side = positions[i][1], right = left + side;
            heights[i] = side;
            for (int j = 0; j < i; j++) {
                int pLeft = positions[j][0], pRight = pLeft + positions[j][1];
                if (pLeft < right && left < pRight) {
                    heights[i] = Math.max(heights[i], heights[j] + side);
                }
            }
            maxH = Math.max(maxH, heights[i]);
            result.add(maxH);
        }
        return result;
    }
}

import java.util.*;

class Solution {
    private int[] tree;
    private int[] lazy;

    public List<Integer> fallingSquares(int[][] positions) {
        Set<Integer> coords = new TreeSet<>();
        for (int[] p : positions) {
            coords.add(p[0]);
            coords.add(p[0] + p[1] - 1);
            coords.add(p[0] + p[1]);
        }
        Map<Integer, Integer> compress = new HashMap<>();
        int idx = 0;
        for (int c : coords) compress.put(c, idx++);
        int sz = idx;
        tree = new int[4 * sz];
        lazy = new int[4 * sz];
        List<Integer> result = new ArrayList<>();
        int maxH = 0;
        for (int[] p : positions) {
            int left = compress.get(p[0]);
            int right = compress.get(p[0] + p[1] - 1);
            int curMax = query(1, 0, sz - 1, left, right);
            int newH = curMax + p[1];
            update(1, 0, sz - 1, left, right, newH);
            maxH = Math.max(maxH, newH);
            result.add(maxH);
        }
        return result;
    }
    private void pushDown(int node) {
        if (lazy[node] > 0) {
            tree[2 * node] = Math.max(tree[2 * node], lazy[node]);
            tree[2 * node + 1] = Math.max(tree[2 * node + 1], lazy[node]);
            lazy[2 * node] = Math.max(lazy[2 * node], lazy[node]);
            lazy[2 * node + 1] = Math.max(lazy[2 * node + 1], lazy[node]);
            lazy[node] = 0;
        }
    }
    private int query(int node, int lo, int hi, int l, int r) {
        if (l > hi || r < lo) return 0;
        if (l <= lo && hi <= r) return tree[node];
        pushDown(node);
        int mid = (lo + hi) / 2;
        return Math.max(query(2 * node, lo, mid, l, r), query(2 * node + 1, mid + 1, hi, l, r));
    }
    private void update(int node, int lo, int hi, int l, int r, int val) {
        if (l > hi || r < lo) return;
        if (l <= lo && hi <= r) {
            tree[node] = Math.max(tree[node], val);
            lazy[node] = Math.max(lazy[node], val);
            return;
        }
        pushDown(node);
        int mid = (lo + hi) / 2;
        update(2 * node, lo, mid, l, r, val);
        update(2 * node + 1, mid + 1, hi, l, r, val);
        tree[node] = Math.max(tree[2 * node], tree[2 * node + 1]);
    }
}
